/*
 * prog24_query_string_parser.c
 *
 * Re‑implementation of the original binary (prog24_query_string_parser).
 * The program reads a single line from stdin, parses it as a URL‑encoded
 * query string (key=value pairs separated by '&'), decodes each key and
 * value, and prints the pairs as “key=value” lines.
 *
 * If no line is read (EOF) the program prints “NO_INPUT”.
 *
 * The decoding follows the usual URL‑encoding rules:
 *   - '+' is translated to a space character.
 *   - “%XY” where X and Y are hexadecimal digits is translated to the
 *     byte with value 0xXY.
 *   - All other characters are copied unchanged.
 *
 * The implementation is deliberately straightforward – it does not
 * retain the obfuscated control flow of the original binary, but it
 * reproduces exactly the same observable output for any given stdin.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 0x800   /* 2048 bytes – same as the original binary */

/* ----------------------------------------------------------------------
 * URL‑decode a string.
 *
 *  src   – pointer to the encoded string
 *  len   – length of the encoded string (may be less than strlen(src))
 *  dst   – buffer where the decoded string will be written; must be large
 *          enough to hold the result (len + 1 is sufficient).
 *
 * The function writes a NUL terminator after the decoded data.
 * ---------------------------------------------------------------------- */
static void url_decode(const char *src, size_t len, char *dst)
{
    size_t i = 0;      /* index in src */
    size_t o = 0;      /* index in dst */

    while (i < len) {
        char c = src[i];

        if (c == '+') {
            dst[o++] = ' ';
            i++;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i + 1]) &&
                   isxdigit((unsigned char)src[i + 2])) {
            /* Convert the two hex digits to a byte */
            char hi = src[i + 1];
            char lo = src[i + 2];
            int hi_val = (hi >= '0' && hi <= '9') ? hi - '0' :
                         (hi >= 'a' && hi <= 'f') ? hi - 'a' + 10 :
                         hi - 'A' + 10;
            int lo_val = (lo >= '0' && lo <= '9') ? lo - '0' :
                         (lo >= 'a' && lo <= 'f') ? lo - 'a' + 10 :
                         lo - 'A' + 10;
            dst[o++] = (char)((hi_val << 4) | lo_val);
            i += 3;
        } else {
            dst[o++] = c;
            i++;
        }
    }
    dst[o] = '\0';
}

/* ----------------------------------------------------------------------
 * Main program – reads a line, parses it, decodes each component and
 * prints the resulting key/value pairs.
 * ---------------------------------------------------------------------- */
int main(void)
{
    static char line[MAX_LINE];
    static char key_buf[MAX_LINE];
    static char val_buf[MAX_LINE];

    /* Read a line from stdin */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* Strip trailing newline and carriage‑return characters */
    size_t line_len = strlen(line);
    while (line_len > 0 &&
          (line[line_len - 1] == '\n' || line[line_len - 1] == '\r')) {
        line[--line_len] = '\0';
    }

    /* Parse the query string: tokens are separated by '&' */
    size_t pos = 0;
    while (pos <= line_len) {
        /* Find the end of the current token */
        size_t token_end = pos;
        while (token_end < line_len && line[token_end] != '&')
            token_end++;

        /* Extract the token (key[=value]) */
        size_t token_len = token_end - pos;
        const char *token = line + pos;

        /* Split token at the first '=' (if any) */
        const char *eq = memchr(token, '=', token_len);
        size_t key_len, val_len;
        const char *key_ptr, *val_ptr;

        if (eq) {
            key_len = (size_t)(eq - token);
            val_len = token_len - key_len - 1;   /* exclude '=' */
            key_ptr = token;
            val_ptr = eq + 1;
        } else {
            /* No '=', the whole token is the key and the value is empty */
            key_len = token_len;
            val_len = 0;
            key_ptr = token;
            val_ptr = "";
        }

        /* Decode key and value */
        url_decode(key_ptr, key_len, key_buf);
        url_decode(val_ptr, val_len, val_buf);

        /* Print the pair */
        printf("%s=%s\n", key_buf, val_buf);

        /* Move to the next token (skip the '&' if present) */
        pos = token_end + 1;
    }

    return 0;
}
